11|// Key step only: no network call. The key lives in state and is cleared
12|// on submit, on reset, and on unmount; never stored, logged, or shared.
13|export function ByokStep({
14|  reason,
15|  note,
16|  privacyNote,
17|  actionLabel,
18|  metaOnly,
19|  initialKey,
20|  onSubmit,
21|}: {
22|  reason?: "too_long" | "free_used";
23|  note?: string;
24|  privacyNote?: string;
25|  actionLabel?: string;
26|  metaOnly?: boolean;
27|  initialKey?: string;
28|  onSubmit: (key: string) => void;
29|}) {
30|  const [provider, setProvider] = useState<Provider>("meta");
31|  const [key, setKey] = useState(initialKey ?? "");
32|  const [baseUrl, setBaseUrl] = useState("");
33|  const [model, setModel] = useState("");
34|  const privacyId = useId();
35|  const urlId = useId();
36|  const urlErrorId = useId();
37|  const freePages = approxPages(FREE_BOOK_MAX_WORDS);
38|
39|  const urlOk = baseUrl.trim() === "" || /^https:\/\//.test(baseUrl.trim());
40|  const ready =
41|    key.trim() !== "" && (provider === "meta" || (urlOk && baseUrl.trim() !== "" && model.trim() !== ""));
42|
43|  const shownProvider = metaOnly ? "meta" : provider;
44|  const reasonLine = note ?? (reason ? REASONS[reason](freePages) : "");
45|  return (
46|    <div>
47|      <h3 className="ob-byok-t">Bring your own key!</h3>
48|      <p className="ob-note">{reasonLine}</p>
49|      {!metaOnly && (
50|      <div className="ob-radio-row" role="radiogroup" aria-label="Key provider">
51|        <label className="ob-radio">
52|          <input
53|            type="radio"
54|            name="byok-provider"
55|            checked={provider === "meta"}
56|            onChange={() => setProvider("meta")}
57|          />
58|          Meta <span className="ob-tag">Recommended</span>
59|        </label>
60|        <label className="ob-radio">
61|          <input
62|            type="radio"
63|            name="byok-provider"
64|            checked={provider === "openai"}
65|            onChange={() => setProvider("openai")}
66|          />
67|          OpenAI-compatible
68|        </label>
69|      </div>
70|      )}
71|      {shownProvider === "openai" && (
72|        <>
73|          <label className="ob-field" htmlFor={urlId}>
74|            Base URL
75|            <input
76|              id={urlId}
77|              className="ob-input"
78|              type="url"
79|              value={baseUrl}
80|              onChange={(event) => setBaseUrl(event.target.value)}
81|              placeholder="https://"
82|              aria-invalid={!urlOk}
83|              aria-describedby={urlOk ? undefined : urlErrorId}
84|            />
85|          </label>
86|          {!urlOk && (
87|            <p className="ob-error" id={urlErrorId}>
88|              The base URL needs to start with https://.
89|            </p>
90|          )}
91|          <label className="ob-field">
92|            Model
93|            <input
94|              className="ob-input"
95|              value={model}
96|              onChange={(event) => setModel(event.target.value)}
97|            />
98|          </label>
99|        </>
100|      )}
101|      <label className="ob-field">
102|        Key
103|        <input
104|          className="ob-input"
105|          type="password"
106|          name="transient-key"
107|          autoComplete="off"
108|          spellCheck={false}
109|          value={key}
110|          onChange={(event) => setKey(event.target.value)}
111|          aria-describedby={privacyId}
112|        />
113|      </label>
114|      <p className="ob-note" id={privacyId}>
115|        {privacyNote ??
116|          "Your key stays in this browser tab. It's never stored on our servers, and it's only used to process this book."}
117|      </p>
118|      <div className="ob-actions">
119|        <button
120|          className="ob-action"
121|          type="button"
122|          disabled={!ready}
123|          onClick={() => {
124|            const entered = key;
125|            setKey("");
126|            onSubmit(entered);
127|          }}
128|        >
129|          {actionLabel ?? "Read with soundtrack"}
130|        </button>
131|      </div>
132|    </div>
133|  );
