1|"use client";
2|
3|import { useEffect, useRef, useState } from "react";
4|import { useRouter } from "next/navigation";
5|import type { RawSection } from "@/core/clean-types";
6|import { EPUB_ERROR_MESSAGES, EpubError, readEpubFileWithSections, type EpubBook } from "@/core/epub";
7|import { UPLOAD_MESSAGES } from "@/core/uploads";
8|import { approxPages, FREE_BOOK_MAX_WORDS, uploadRoute } from "@/core/upload-policy";
9|import { TurnstileWidget } from "../turnstile";
10|import { BookCard } from "./book-card";
11|import { ByokStep } from "./byok";
12|import { countFreeBookToday, getFreeBooksToday } from "./free-book";
13|import { HomeIcon } from "./home-icons";
14|import { saveMyBook } from "./my-books";
15|import { driveUpload, UploadFlowError, type FlowCode, type FlowProgress } from "./upload-flow";
16|
17|interface ParsedBook {
18|  book: EpubBook;
19|  sections: RawSection[];
20|}
21|
22|type Status =
23|  | { step: "idle" }
24|  | { step: "reading" }
25|  | { step: "error"; message: string }
26|  | { step: "parsed"; parsed: ParsedBook }
27|  | { step: "working"; parsed: ParsedBook; key: string | null; progress: FlowProgress | null }
28|  | { step: "finishing"; parsed: ParsedBook; id: string; progress: FlowProgress }
29|  | {
30|      step: "failed";
31|      parsed: ParsedBook;
32|      key: string | null;
33|      code: FlowCode;
34|      progress: FlowProgress | null;
35|    };
36|
37|const NETWORK_MESSAGE = "We lost the connection for a moment. Try again?";
38|
39|function progressCopy(progress: FlowProgress | null): string {
40|  if (!progress) return "Reading your book…";
41|  if (progress.total > 0 && progress.done >= progress.total) return "Setting it to music…";
42|  if (progress.done <= 0) return "Finding the scenes…";
43|  return `Listening for the mood of chapter ${progress.done + 1} of ${progress.total}…`;
44|}
45|
46|function progressPercent(progress: FlowProgress | null): number {
47|  if (!progress || progress.total <= 0) return 0;
48|  return Math.min(100, Math.round((progress.done / progress.total) * 100));
49|}
50|
51|// Client upload: the EPUB parses in the browser, then the sections POST
52|// to /api/uploads and the steps run until done. Keys live in state only.
53|export function UploadSection() {
54|  const router = useRouter();
55|  const [status, setStatus] = useState<Status>({ step: "idle" });
56|  const [dragging, setDragging] = useState(false);
57|  const [freeCount, setFreeCount] = useState(0);
58|  const [coverUrl, setCoverUrl] = useState<string | null>(null);
59|  const [keyOpen, setKeyOpen] = useState(false);
60|  // Tab-only scratch: never stored, logged, or sent; dies with this component.
61|  const [idleKey, setIdleKey] = useState("");
62|  const [showKey, setShowKey] = useState(false);
63|  const inputRef = useRef<HTMLInputElement>(null);
64|  const resultRef = useRef<HTMLDivElement>(null);
65|  const runRef = useRef(0);
66|  const abortRef = useRef<AbortController | null>(null);
67|  const freePages = approxPages(FREE_BOOK_MAX_WORDS);
68|
69|  useEffect(() => setFreeCount(getFreeBooksToday()), []);
70|  useEffect(() => () => abortRef.current?.abort(), []);
71|
72|  // The result views replace the drop zone, so move focus into the
73|  // result; otherwise keyboard focus is lost when it unmounts.
74|  useEffect(() => {
75|    if (status.step !== "idle" && status.step !== "reading" && status.step !== "error") {
76|      resultRef.current?.focus();
77|    }
78|  }, [status]);
79|
80|  const parsed =
81|    status.step === "parsed" ||
82|    status.step === "working" ||
83|    status.step === "finishing" ||
84|    status.step === "failed"
85|      ? status.parsed
86|      : null;
87|  const book = parsed?.book ?? null;
88|  useEffect(() => {
89|    if (!book?.cover) {
90|      setCoverUrl(null);
91|      return;
92|    }
93|    const url = URL.createObjectURL(new Blob([book.cover.bytes as BlobPart], { type: book.cover.mediaType }));
94|    setCoverUrl(url);
95|    return () => URL.revokeObjectURL(url);
96|  }, [book]);
97|
98|  async function openFile(file: File) {
99|    setStatus({ step: "reading" });
100|    try {
101|      const { book: parsedBook, sections } = await readEpubFileWithSections(file);
102|      setStatus({ step: "parsed", parsed: { book: parsedBook, sections } });
103|    } catch (err) {
104|      const message =
105|        err instanceof EpubError ? EPUB_ERROR_MESSAGES[err.code] : EPUB_ERROR_MESSAGES.unreadable;
106|      setStatus({ step: "error", message });
107|    }
108|  }
109|
110|  function reset() {
111|    runRef.current += 1;
112|    abortRef.current?.abort();
113|    abortRef.current = null;
114|    if (inputRef.current) inputRef.current.value = "";
115|    setIdleKey("");
116|    setShowKey(false);
117|    setStatus({ step: "idle" });
118|  }
119|
120|  function startDrive(
121|    next: ParsedBook,
122|    opts: { key: string | null; token?: string | null; jobId?: string | null; progress?: FlowProgress | null },
123|  ) {
124|    abortRef.current?.abort();
125|    const ctrl = new AbortController();
126|    abortRef.current = ctrl;
127|    const run = (runRef.current += 1);
128|    const alive = (): boolean => runRef.current === run && !ctrl.signal.aborted;
129|    const key = opts.key;
130|    let counted = opts.jobId != null;
131|    let latest = opts.progress ?? null;
132|    setStatus({ step: "working", parsed: next, key, progress: latest });
133|    void driveUpload({
134|      title: next.book.title,
135|      author: next.book.author,
136|      sections: next.sections,
137|      key,
138|      token: opts.token ?? null,
139|      jobId: opts.jobId ?? null,
140|      signal: ctrl.signal,
141|      onProgress: (progress) => {
142|        if (!alive()) return;
143|        if (!counted) {
144|          counted = true;
145|          if (!key) {
146|            countFreeBookToday();
147|            setFreeCount(getFreeBooksToday());
148|          }
149|        }
150|        latest = progress;
151|        setStatus({ step: "working", parsed: next, key, progress });
152|      },
153|    }).then(
154|      ({ id, chapters }) => {
155|        if (!alive()) return;
156|        saveMyBook({ id, title: next.book.title, author: next.book.author ?? "Unknown author", savedAt: Date.now() });
157|        setStatus({
158|          step: "finishing",
159|          parsed: next,
160|          id,
161|          progress: latest ?? { jobId: id, done: 1, total: 1, chapters },
162|        });
163|        router.push(`/read/${id}`);
164|      },
165|      (err: unknown) => {
166|        if (!alive()) return;
167|        if (err instanceof UploadFlowError) {
168|          setStatus({ step: "failed", parsed: next, key, code: err.code, progress: latest });
169|          return;
170|        }
171|        setStatus({ step: "failed", parsed: next, key, code: "unavailable", progress: latest });
172|      },
173|    );
174|  }
175|
176|  const route = status.step === "parsed" ? uploadRoute(status.parsed.book.words, freeCount) : null;
177|
178|  if (status.step === "working" || status.step === "finishing") {
179|    const progress = status.progress;
180|    return (
181|      <section className="ob-bring" aria-label="Bring your own book">
182|        <div ref={resultRef} tabIndex={-1}>
183|          <BookCard book={status.parsed.book} coverUrl={coverUrl} />
184|          <div
185|            className="ob-progress"
186|            role="progressbar"
187|            aria-label="Preparing your book"
188|            aria-valuemin={0}
189|            aria-valuemax={100}
190|            aria-valuenow={progressPercent(progress)}
191|          >
192|            <div className="ob-progress-fill" style={{ width: `${progressPercent(progress)}%` }} />
193|          </div>
194|          <p className="ob-note" aria-live="polite">
195|            {progressCopy(progress)}
196|          </p>
197|        </div>
198|      </section>
199|    );
200|  }
201|
202|  if (status.step === "failed") {
203|    return (
204|      <section className="ob-bring" aria-label="Bring your own book">
205|        <div ref={resultRef} tabIndex={-1}>
206|          <BookCard book={status.parsed.book} coverUrl={coverUrl} />
207|          <FailedView
208|            status={status}
209|            idleKey={idleKey}
210|            onRetryKey={(key) =>
211|              startDrive(status.parsed, { key, progress: null })
212|            }
213|            onRetryToken={(token) =>
214|              startDrive(status.parsed, {
215|                key: status.key,
216|                token,
217|                jobId: status.progress?.jobId ?? null,
218|                progress: status.progress,
219|              })
220|            }
221|            onRetry={() =>
222|              startDrive(status.parsed, {
223|                key: status.key,
224|                jobId: status.progress?.jobId ?? null,
225|                progress: status.progress,
226|              })
227|            }
228|            onReset={reset}
229|          />
230|        </div>
231|      </section>
232|    );
233|  }
234|
235|  return (
236|    <section className="ob-bring" aria-label="Bring your own book">
237|      {status.step === "parsed" && route ? (
238|        <div ref={resultRef} tabIndex={-1}>
239|          <BookCard book={status.parsed.book} coverUrl={coverUrl} />
240|          {route.kind === "free" ? (
241|            <div className="ob-actions">
242|              <button
243|                className="ob-action"
244|                type="button"
245|                onClick={() => startDrive(status.parsed, { key: null })}
246|              >
247|                Read with soundtrack
248|              </button>
249|              <button className="ob-quiet" type="button" onClick={reset}>
250|                Choose another book
251|              </button>
252|            </div>
253|          ) : (
254|            <div>
255|              <ByokStep
256|                metaOnly
257|                reason={route.reason}
258|                initialKey={idleKey}
259|                onSubmit={(key) => {
260|                  setIdleKey("");
261|                  setShowKey(false);
262|                  startDrive(status.parsed, { key });
263|                }}
264|              />
265|              <div className="ob-actions">
266|                <button className="ob-quiet" type="button" onClick={reset}>
267|                  Choose another book
268|                </button>
269|              </div>
270|            </div>
271|          )}
272|        </div>
273|      ) : (
274|        <div>
275|          <div
276|            className={dragging ? "ob-drop over" : "ob-drop"}
277|            role="button"
278|            tabIndex={0}
279|            aria-label="Drop an EPUB here, or choose a file"
280|            onClick={() => inputRef.current?.click()}
281|            onKeyDown={(event) => {
282|              if (event.key === "Enter" || event.key === " ") {
283|                event.preventDefault();
284|                inputRef.current?.click();
285|              }
286|            }}
287|            onDragEnter={(event) => {
288|              event.preventDefault();
289|              setDragging(true);
290|            }}
291|            onDragOver={(event) => event.preventDefault()}
292|            onDragLeave={() => setDragging(false)}
293|            onDrop={(event) => {
294|              event.preventDefault();
295|              setDragging(false);
296|              const file = event.dataTransfer.files?.[0];
297|              if (file) void openFile(file);
298|            }}
299|          >
300|            <HomeIcon name="upload" />
301|            <p>
302|              Drop an EPUB here, or <span className="ob-pick">choose a file</span>
303|            </p>
304|            <small>EPUB only, up to 20 MB. Nothing leaves your computer until you choose to read it.</small>
305|            <input
306|              ref={inputRef}
307|              type="file"
308|              accept=".epub,application/epub+zip"
309|              hidden
310|              aria-hidden="true"
311|              tabIndex={-1}
312|              onChange={(event) => {
313|                const file = event.target.files?.[0];
314|                if (file) void openFile(file);
315|              }}
316|            />
317|          </div>
318|          <div aria-live="polite">
319|            {status.step === "reading" && <p className="ob-file">Opening your book…</p>}
320|            {status.step === "error" && (
321|              <div className="ob-file-row">
322|                <p className="ob-file ob-err">{status.message}</p>
323|                <button className="ob-quiet" type="button" onClick={reset}>
324|                  Try another file
325|                </button>
326|              </div>
327|            )}
328|          </div>
329|          <div className="ob-picks" role="group" aria-label="How much reading to take">
330|            <button
331|              type="button"
332|              className="ob-pickbtn"
333|              aria-pressed={!keyOpen}
334|              onClick={() => {
335|                setKeyOpen(false);
336|                setIdleKey("");
337|                setShowKey(false);
338|              }}
339|            >
340|              <span className="ob-box" aria-hidden="true">
341|                <HomeIcon name="check-box" />
342|              </span>
343|              <span>
344|                <b>Free</b>
345|                <small>Two books a day are on us, up to about {freePages} pages each.</small>
346|              </span>
347|            </button>
348|            <button
349|              type="button"
350|              className="ob-pickbtn"
351|              aria-pressed={keyOpen}
352|              aria-expanded={keyOpen}
353|              aria-controls="obKeybox"
354|              onClick={() => {
355|                if (keyOpen) {
356|                  setIdleKey("");
357|                  setShowKey(false);
358|                }
359|                setKeyOpen(!keyOpen);
360|              }}
361|            >
362|              <span className="ob-keydoodle" aria-hidden="true">
363|                <HomeIcon name="key" />
364|              </span>
365|              <span>
366|                <b>Bring your own key!</b>
367|                <small>Longer books, or more of them? Use your own Meta key.</small>
368|              </span>
369|            </button>
370|          </div>
371|          <div className="ob-keybox" id="obKeybox" hidden={!keyOpen}>
372|            <div className="ob-keyrow">
373|              <label className="sr-only" htmlFor="obKey">
374|                Paste your API key
375|              </label>
376|              <input
377|                id="obKey"
378|                type={showKey ? "text" : "password"}
379|                placeholder="Paste your API key"
380|                autoComplete="off"
381|                spellCheck={false}
382|                name="transient-key"
383|                value={idleKey}
384|                onChange={(event) => setIdleKey(event.target.value)}
385|              />
386|              <button
387|                type="button"
388|                className="ob-eye"
389|                aria-label={showKey ? "Hide API key" : "Show API key"}
390|                aria-pressed={showKey}
391|                onClick={() => setShowKey((show) => !show)}
392|              >
393|                <HomeIcon name={showKey ? "eye-off" : "eye"} />
394|              </button>
395|            </div>
396|            <p className="ob-fine">It stays in this tab only. We never save it.</p>
397|          </div>
398|        </div>
399|      )}
400|    </section>
401|  );
402|}
