404|// One failed upload: coded errors map to the next step, never a dead end.
405|function FailedView({
406|  status,
407|  idleKey,
408|  onRetryKey,
409|  onRetryToken,
410|  onRetry,
411|  onReset,
412|}: {
413|  status: Extract<Status, { step: "failed" }>;
414|  idleKey: string;
