443|        <TurnstileWidget onToken={onRetryToken} />
444|        <div className="ob-actions">
445|          <button className="ob-action" type="button" onClick={onRetry}>
446|            Try again
447|          </button>
448|          <button className="ob-quiet" type="button" onClick={onReset}>
449|            Choose another book
450|          </button>
451|        </div>
452|      </div>
453|    );
454|  }
455|  if (code === "expired" || code === "not_found") {
456|    return (
457|      <div>
458|        <p className="ob-note">{UPLOAD_MESSAGES[code]} Upload it again to start over.</p>
459|        <div className="ob-actions">
460|          <button className="ob-action" type="button" onClick={onReset}>
461|            Upload it again
462|          </button>
463|        </div>
464|      </div>
465|    );
466|  }
467|  return (
468|    <div>
469|      <p className="ob-note" role="alert">
