15|(globalThis as { IS_REACT_ACT_ENVIRONMENT?: boolean }).IS_REACT_ACT_ENVIRONMENT = true;
16|
17|let container: HTMLDivElement;
18|let root: Root | null = null;
19|
20|function click(el: Element) {
21|  act(() => {
22|    el.dispatchEvent(new MouseEvent("click", { bubbles: true }));
23|  });
24|}
25|
26|function shelfButton(id: string): HTMLButtonElement {
27|  const el = container.querySelector(`.lb-item[data-book="${id}"]`);
28|  if (!(el instanceof HTMLButtonElement)) throw new Error(`shelf button missing: ${id}`);
29|  return el;
30|}
31|
32|beforeEach(() => {
33|  try {
34|    window.localStorage.clear();
35|  } catch {
36|    // jsdom without storage: the shelf tolerates it.
37|  }
