39|  container = document.createElement("div");
40|  document.body.appendChild(container);
41|  act(() => {
42|    root = createRoot(container);
43|  });
44|  act(() => {
45|    root?.render(<HomeSpread />);
46|  });
47|});
48|
49|afterEach(() => {
50|  act(() => {
51|    root?.unmount();
52|  });
53|  root = null;
54|  container.remove();
55|});
56|
57|describe("shelf links", () => {
58|  test("each ready book starts reading at /read/<id>", () => {
59|    const ready = shelf.filter((book) => book.ready);
60|    expect(ready.length).toBeGreaterThan(0);
61|    for (const book of ready) {
62|      click(shelfButton(book.id));
63|      const link = container.querySelector("a.ob-read");
64|      expect(link?.getAttribute("href")).toBe(`/read/${book.id}`);
65|    }
66|  });
67|
68|  test("every book on the shelf opens its own reader", () => {
69|    expect(shelf.every((book) => book.ready)).toBe(true);
70|    for (const book of shelf) {
71|      click(shelfButton(book.id));
72|      expect(container.querySelector(".ob-cta-soon")).toBeNull();
73|      expect(container.querySelector("a.ob-read")?.getAttribute("href")).toBe(`/read/${book.id}`);
74|    }
75|  });
76|});
