13|  if (start < 0) throw new Error("no narrow block");
14|  const open = css.indexOf("{", start);
15|  let depth = 0;
16|  for (let i = open; i < css.length; i++) {
17|    if (css.charAt(i) === "{") depth++;
18|    else if (css.charAt(i) === "}") {
19|      depth--;
20|      if (depth === 0) return css.slice(open, i + 1);
21|    }
22|  }
23|  throw new Error("unbalanced narrow block");
24|}
