42|    expect(css).toMatch(/\.style-menu-key\s*\{[^}]*display:\s*none/);
43|    expect(css).toMatch(/\.warmth input\s*\{[^}]*width:\s*44px/);
44|  });
45|
46|  it("keeps the desktop grid above 1024px", () => {
